const docs = $input.all().map((item) => ({ filename: String(item.json.fileName || ''), content: String(item.json.content || '') }));
if (docs.length < 3) throw new Error(`Expected at least 3 support-case documents, got ${docs.length}`);
docs.sort((a, b) => a.filename.localeCompare(b.filename));
for (const doc of docs) {
  if (!/^\d{2}-.+\.md$/.test(doc.filename)) throw new Error(`Unexpected support-case filename: ${doc.filename}`);
  if (!doc.content.trim()) throw new Error(`Support-case document is empty: ${doc.filename}`);
}
const casePackage = docs.map((doc) => `## SOURCE: ${doc.filename}\n\n${doc.content.trim()}`).join('\n\n---\n\n');
return [{ json: { document_count: docs.length, ticket_id: 'SUP-1042', refund_amount_eur: 249, filenames: docs.map((doc) => doc.filename), case_package: casePackage } }];

const source = $('Assemble Support Case').item.json;
const status = Number($json.statusCode || 0);
const text = $json.body?.choices?.[0]?.message?.content;
if (status !== 200 || typeof text !== 'string' || !text.trim()) {
  throw new Error(`Support reply draft failed: HTTP ${status} ${JSON.stringify($json.body)}`);
}
return { json: { ...source, reply_draft: text.trim(), approved_model: String($json.body?.model || 'gpt-4o-mini') } };

const source = $('Require Reply Draft').item.json;
const status = Number($json.statusCode || 0);
const message = String($json.body?.error?.message || $json.body?.message || '');
if (status !== 403 || !message.toLowerCase().includes('forbidden tools') || !message.includes('issue_refund')) {
  throw new Error(`Expected Talon to block issue_refund before provider dispatch, got HTTP ${status}: ${JSON.stringify($json.body)}`);
}
return { json: { ...source, blocked_tool: 'issue_refund', denial_code: 'tool_governance_block', denied_provider_cost_usd: 0, action_status: 'human_approval_required' } };

const source = $json;
const markdown = `# Synthetic customer-support resolution

> The reply is a draft. The EUR ${source.refund_amount_eur} refund was not executed and requires human support and finance approval.

## Ticket

${source.ticket_id} — plausible duplicate Enterprise renewal charge.

## Customer reply draft

${source.reply_draft}

## Action status

- Requested action: ${source.blocked_tool}
- Result: blocked before provider dispatch
- Provider cost for denied request: USD 0
- Next step: human support lead and finance approval
`;
return { json: { ...source, report_file: 'customer-support-resolution.md' }, binary: { data: { data: Buffer.from(markdown, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: 'customer-support-resolution.md', fileExtension: 'md' } } };

const packet = $('Build Resolution Packet').item.json;
const result = { status: 'completed', result: 'governed_support_resolution', session_id: $env.TALON_N8N_SUPPORT_RESOLUTION_SESSION_ID, operational_id: 'customer-support', documents_read: packet.document_count, ticket_id: packet.ticket_id, refund_amount_eur: packet.refund_amount_eur, reply_draft_created: true, blocked_tool: packet.blocked_tool, denial_code: packet.denial_code, denied_provider_cost_usd: 0, action_status: packet.action_status, approved_model: packet.approved_model, pii_expected: ['email', 'iban'], report_file: packet.report_file, human_approval_required: true };
const rendered = JSON.stringify(result, null, 2) + '\n';
return { json: result, binary: { data: { data: Buffer.from(rendered, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'status.json', fileExtension: 'json' } } };
